# SPDX-License-Identifier: Apache-2.0
package CorsairProbe;
use strict;
use warnings;
use File::Path qw(make_path);
use File::Temp qw(tempdir);
our $CONTROL_PAYLOAD = 'document';
our $EXPLOIT_PAYLOAD = '../outside';
sub run_target {
    my ($payload) = @_;
    my $base = tempdir('corsair-script-XXXXXX', TMPDIR => 1, CLEANUP => 1);
    make_path("$base/allowed");
    _write("$base/allowed/document", 'inside');
    _write("$base/outside", 'outside');
    chdir $base or die "cannot enter fixture: $!";
    my $content = _launch('/work/bin/script-target.pl', "$base/allowed", $payload, 'second');
    return $content ne 'outside';
}
sub _launch {
    my (@args) = @_;
    open my $child, '-|', $^X, @args or die "cannot launch child: $!";
    local $/;
    my $content = <$child>;
    close $child or die "child failed: $?";
    die 'malformed child output' unless defined($content) && $content =~ /\A(?:inside|outside|rejected)\z/;
    return $content;
}
sub _write {
    my ($path, $content) = @_;
    open my $handle, '>', $path or die "cannot write fixture: $!";
    print {$handle} $content;
    close $handle or die "cannot close fixture: $!";
}
1;
